SELECT sbcam.id
FROM small_bag_cost_allocation_main sbcam
WHERE sbcam.is_deleted = false
  AND sbcam.report_date = #{reportPeriodStr}

    AND sbcam.report_status != #{reportStatus}


    AND (sbcam.big_table_status IS NULL OR sbcam.big_table_status != #{bigTableDoneCode})


    AND sbcam.id > #{lastId}

ORDER BY sbcam.id ASC
LIMIT #{batchSize}

SELECT COUNT(1)
FROM small_bag_cost_allocation_main sbcam
WHERE sbcam.is_deleted = false
  AND sbcam.report_date = #{reportPeriodStr}

    AND sbcam.report_status != #{reportStatus}


    AND (sbcam.big_table_status IS NULL OR sbcam.big_table_status != #{bigTableDoneCode})

SELECT sbcam.id
FROM small_bag_cost_allocation_main sbcam
WHERE sbcam.is_deleted = false
  AND sbcam.report_date = #{reportPeriodStr}
  AND sbcam.report_status = #{reportStatus}

    AND sbcam.id > #{lastId}

ORDER BY sbcam.id ASC
LIMIT #{batchSize}

SELECT COUNT(1)
FROM small_bag_cost_allocation_main sbcam
WHERE sbcam.is_deleted = false
  AND sbcam.report_date = #{reportPeriodStr}
  AND sbcam.report_status = #{reportStatus}
